#!/usr/bin/env python3
"""Strict CSV parsing, formatting, JSON conversion, and command-line support."""

import csv
import io
import json
import sys


_HEADER = ["name", "note"]
_KEYS = {"name", "note"}


def _validate_quoting(text):
    """Reject quotes that do not follow CSV field-quoting rules."""
    in_quotes = False
    at_field_start = True
    just_closed = False
    index = 0

    while index < len(text):
        char = text[index]

        if in_quotes:
            if char == '"':
                if index + 1 < len(text) and text[index + 1] == '"':
                    index += 2
                    continue
                in_quotes = False
                just_closed = True
            index += 1
            continue

        if just_closed:
            if char == ",":
                just_closed = False
                at_field_start = True
            elif char == "\n":
                just_closed = False
                at_field_start = True
            elif char == "\r":
                just_closed = False
                at_field_start = True
                if index + 1 < len(text) and text[index + 1] == "\n":
                    index += 1
            else:
                raise ValueError(
                    "malformed CSV: unexpected character after closing quote"
                )
            index += 1
            continue

        if char == '"':
            if not at_field_start:
                raise ValueError("malformed CSV: quote inside an unquoted field")
            in_quotes = True
            at_field_start = False
        elif char == ",":
            at_field_start = True
        elif char == "\n":
            at_field_start = True
        elif char == "\r":
            at_field_start = True
            if index + 1 < len(text) and text[index + 1] == "\n":
                index += 1
        else:
            at_field_start = False
        index += 1

    if in_quotes:
        raise ValueError("malformed CSV: unterminated quoted field")


def parse_records(text):
    """Parse CSV with the exact header ``name,note`` into dictionaries."""
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")

    _validate_quoting(text)
    stream = io.StringIO(text, newline="")
    reader = csv.reader(stream, strict=True)

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("missing CSV header; expected name,note") from None
    except csv.Error as error:
        raise ValueError(f"malformed CSV: {error}") from None

    if header != _HEADER:
        raise ValueError("invalid CSV header; expected exactly name,note")

    records = []
    try:
        for row_number, row in enumerate(reader, start=2):
            if len(row) != 2:
                raise ValueError(
                    f"invalid column count on row {row_number}: expected 2, got {len(row)}"
                )
            records.append({"name": row[0], "note": row[1]})
    except csv.Error as error:
        raise ValueError(f"malformed CSV: {error}") from None

    return records


def format_records(records):
    """Serialize validated records as CSV using LF line terminators."""
    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)

    try:
        iterator = iter(records)
    except TypeError:
        raise ValueError("records must be an iterable of dictionaries") from None

    for position, record in enumerate(iterator, start=1):
        if not isinstance(record, dict):
            raise ValueError(f"record {position} must be a dictionary")
        if set(record) != _KEYS:
            raise ValueError(
                f"record {position} must contain exactly the keys name and note"
            )
        if not isinstance(record["name"], str) or not isinstance(record["note"], str):
            raise ValueError(f"record {position} values must be strings")
        try:
            writer.writerow([record["name"], record["note"]])
        except (csv.Error, TypeError) as error:
            raise ValueError(f"could not format record {position}: {error}") from None

    return output.getvalue()


def to_json(text):
    """Convert valid CSV text to JSON without ASCII-escaping Unicode values."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main():
    """Run the stdin-to-JSON command-line interface."""
    try:
        result = to_json(sys.stdin.read())
    except ValueError as error:
        sys.stderr.write(f"Error: {error}\n")
        return 2

    sys.stdout.write(result + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Independent behavioral tests for csv_tool.py.

Run from the directory containing csv_tool.py with:
    python -m unittest -v test_csv_tool.py
"""

import json
from pathlib import Path
import subprocess
import sys
import unittest

import csv_tool


class ParseRecordsTests(unittest.TestCase):
    def test_01_simple_records(self):
        self.assertEqual(
            csv_tool.parse_records("name,note\nAlice,hello\nBob,world\n"),
            [
                {"name": "Alice", "note": "hello"},
                {"name": "Bob", "note": "world"},
            ],
        )

    def test_02_quoted_comma(self):
        self.assertEqual(
            csv_tool.parse_records('name,note\nAlice,"hello, world"\n'),
            [{"name": "Alice", "note": "hello, world"}],
        )

    def test_03_doubled_quotes(self):
        self.assertEqual(
            csv_tool.parse_records('name,note\nAlice,"She said ""hi"""\n'),
            [{"name": "Alice", "note": 'She said "hi"'}],
        )

    def test_04_embedded_newlines(self):
        self.assertEqual(
            csv_tool.parse_records('name,note\nAlice,"first line\nsecond line"\n'),
            [{"name": "Alice", "note": "first line\nsecond line"}],
        )

    def test_05_crlf_input(self):
        self.assertEqual(
            csv_tool.parse_records("name,note\r\nAlice,hello\r\nBob,world\r\n"),
            [
                {"name": "Alice", "note": "hello"},
                {"name": "Bob", "note": "world"},
            ],
        )

    def test_06_unicode_and_empty_fields(self):
        self.assertEqual(
            csv_tool.parse_records("name,note\nZoë,雪 ☃\n,\n"),
            [
                {"name": "Zoë", "note": "雪 ☃"},
                {"name": "", "note": ""},
            ],
        )

    def test_07_empty_input_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records("")

    def test_08_header_only_is_empty_record_list(self):
        self.assertEqual(csv_tool.parse_records("name,note\n"), [])

    def test_09_wrong_header_rejected(self):
        cases = (
            "note,name\n",
            "name,notes\n",
            "Name,note\n",
            "name\n",
            "name,note,extra\n",
        )
        for text in cases:
            with self.subTest(text=text), self.assertRaises(ValueError):
                csv_tool.parse_records(text)

    def test_10_too_few_columns_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records("name,note\nAlice\n")

    def test_11_too_many_columns_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records("name,note\nAlice,hello,extra\n")

    def test_12_malformed_quoting_rejected(self):
        cases = (
            'name,note\nAlice,"unterminated\n',
            'name,note\nAlice,"closed"junk\n',
        )
        for text in cases:
            with self.subTest(text=text), self.assertRaises(ValueError):
                csv_tool.parse_records(text)


class FormatRecordsTests(unittest.TestCase):
    def test_13_simple_output_uses_lf(self):
        result = csv_tool.format_records([{"name": "Alice", "note": "hello"}])
        self.assertEqual(result, "name,note\nAlice,hello\n")
        self.assertNotIn("\r", result)

    def test_14_commas_and_quotes_are_escaped(self):
        self.assertEqual(
            csv_tool.format_records(
                [{"name": "A", "note": 'comma, and "quote"'}]
            ),
            'name,note\nA,"comma, and ""quote"""\n',
        )

    def test_15_embedded_newline_is_preserved(self):
        text = csv_tool.format_records(
            [{"name": "A", "note": "line one\nline two"}]
        )
        self.assertEqual(text, 'name,note\nA,"line one\nline two"\n')
        self.assertEqual(
            csv_tool.parse_records(text),
            [{"name": "A", "note": "line one\nline two"}],
        )

    def test_16_empty_record_sequence(self):
        self.assertEqual(csv_tool.format_records([]), "name,note\n")

    def test_17_missing_key_rejected(self):
        for record in ({"name": "A"}, {"note": "B"}):
            with self.subTest(record=record), self.assertRaises(ValueError):
                csv_tool.format_records([record])

    def test_18_extra_key_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.format_records(
                [{"name": "A", "note": "B", "extra": "C"}]
            )

    def test_19_non_string_value_rejected(self):
        records = (
            {"name": 1, "note": "B"},
            {"name": "A", "note": None},
            {"name": "A", "note": ["B"]},
        )
        for record in records:
            with self.subTest(record=record), self.assertRaises(ValueError):
                csv_tool.format_records([record])

    def test_20_non_mapping_record_rejected_as_value_error(self):
        with self.assertRaises(ValueError):
            csv_tool.format_records([("A", "B")])


class JsonTests(unittest.TestCase):
    def test_21_json_fidelity(self):
        source = 'name,note\n"Zoë, Jr.","first\nsecond: ""雪"""\n'
        encoded = csv_tool.to_json(source)
        self.assertEqual(
            json.loads(encoded),
            [{"name": "Zoë, Jr.", "note": 'first\nsecond: "雪"'}],
        )

    def test_22_invalid_csv_raises_value_error(self):
        with self.assertRaises(ValueError):
            csv_tool.to_json("wrong,note\nA,B\n")


class CliTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.script = str(Path(csv_tool.__file__).resolve())

    def run_cli(self, stdin):
        return subprocess.run(
            [sys.executable, self.script],
            input=stdin,
            text=True,
            capture_output=True,
            check=False,
        )

    def test_23_success_stdout_only_and_exit_zero(self):
        completed = self.run_cli("name,note\nAlice,hello\n")
        self.assertEqual(completed.returncode, 0)
        self.assertEqual(completed.stderr, "")
        self.assertEqual(
            json.loads(completed.stdout),
            [{"name": "Alice", "note": "hello"}],
        )

    def test_24_invalid_header_uses_stderr_and_exit_two(self):
        completed = self.run_cli("wrong,note\nAlice,hello\n")
        self.assertEqual(completed.returncode, 2)
        self.assertEqual(completed.stdout, "")
        self.assertTrue(completed.stderr.strip())
        self.assertNotIn("Traceback", completed.stderr)

    def test_25_malformed_csv_uses_stderr_and_exit_two(self):
        completed = self.run_cli('name,note\nAlice,"unterminated\n')
        self.assertEqual(completed.returncode, 2)
        self.assertEqual(completed.stdout, "")
        self.assertTrue(completed.stderr.strip())
        self.assertNotIn("Traceback", completed.stderr)

    def test_26_cli_preserves_unicode_newlines_and_quotes(self):
        source = 'name,note\n雪,"one\ntwo ""quoted"""\n'
        completed = self.run_cli(source)
        self.assertEqual(completed.returncode, 0)
        self.assertEqual(completed.stderr, "")
        self.assertEqual(
            json.loads(completed.stdout),
            [{"name": "雪", "note": 'one\ntwo "quoted"'}],
        )


if __name__ == "__main__":
    unittest.main()
